 let rows=[];if(account){try{const d=JSON.parse(localStorage.getItem('cb-v2-linked-broker-trades::'+account)||'{}')||{};const tradeId=t=>String(t.clientTradeId??t.client_trade_id??t.positionId??t.position_id??t.tradeLockerId??t.id??'');rows=(Array.isArray(d.rows)?d.rows:[]).filter(t=>d.links?.[tradeId(t)]===setup.id).map(t=>({key:'broker:'+account+':'+tradeId(t),label:String(t.symbol??t.symbolName??t.instrumentName??'TRADE')})).filter(t=>!t.key.endsWith(':'));}catch(e){console.warn('Result entry lookup unavailable',e)}}
